// One readable Slack message per failed run.
// Works for failed executions and for trigger errors (for example an expired Gmail login).
const d = $input.first().json;
const wf = d.workflow || {};
const ex = d.execution || null;
const err = (ex && ex.error) || (d.trigger && d.trigger.error) || {};
const when = $now.setZone('America/Los_Angeles').toFormat('ccc, LLL d, h:mm a') + ' PT';
const nodeName = (ex && ex.lastNodeExecuted) || (err.node && err.node.name) || (d.trigger ? 'trigger' : 'unknown');

const lines = [
  ':x: *' + (wf.name || 'A workflow') + '* stopped with an error (' + when + ').',
  '*Node:* ' + nodeName,
  '*Error:* ' + String(err.message || err.description || 'no message').slice(0, 300),
];
if (ex && ex.id) {
  lines.push('*Execution:* ' + ex.id + (ex.url ? ' · <' + ex.url + '|open in n8n>' : ''));
} else {
  lines.push('The trigger itself failed, so no execution was saved. Check the trigger and its credential.');
}
if (/Support Agent/i.test(wf.name || '')) {
  lines.push('If this run came from a customer email, the customer may not have received a reply. Check the support inbox.');
}
return [{ json: { text: lines.join('\n') } }];
